  remaining: number;
  limit: number;
  used: number;
  group: string | null;
  errorLimitRemain: number;
  errorLimitReset: number;
  retryAfter: number | null;
  blockedUntil: number;
};
```

**How to access:** Via `apiClient.getRateLimiter().getStatus()` (not exposed in response metadata)

